<template>
<div class="admin-news">
<nav class="tabs" aria-label="新闻后台栏目"><button v-for="tab in tabs" :key="tab.key" :aria-current="section===tab.key ? 'page' : undefined" @click="switchSection(tab.key)" :disabled="busy||!!editing">{{ tab.name }}</button></nav>
<NewsEditor v-if="editing" :key="editing.id || 'new'" :article="editing" allow-media @saved="saved" @cancel="editing=null" />
<main v-else>
<header class="heading"><div><p>跃科官网 · 新闻运营</p><h1>{{ selected ? '文章工作区' : tabs.find(tab=>tab.key===section)?.name }}</h1></div><div class="actions"><button @click="refreshAll" :disabled="busy||loading">刷新</button><button v-if="!selected" @click="openPackageImport" :disabled="busy||loading">导入新闻包</button><button class="primary" @click="editing={}" :disabled="busy">撰写新闻</button><a href="/news">查看官网资讯 ↗</a></div></header>
<p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="loading" role="status">正在读取官网内容…</p>
<template v-if="selected">
<header class="article-heading"><button @click="closeArticle" :disabled="busy">返回列表</button><div><h2>{{ selected.title }}</h2><p>{{ selected.revisionId ? '私有修订稿 · 原公开正文保持原版本' : selected.editorialStateName }} · 内容版本 {{ selected.packageVersion }}</p></div><a v-if="selected.publishedAt" :href="selected.url">查看公开页 ↗</a></header>
<p v-if="selected.reviewReason" class="notice">退回／处理说明：{{ selected.reviewReason }}</p><p v-if="selected.scheduledAt" class="notice">计划发布时间（北京时间）：{{ date(selected.scheduledAt) }}</p><p v-if="selected.issue" class="error">校验说明：{{ selected.issue }}</p>
<div class="article-actions">
<button v-if="editable" @click="editing=selected">继续编辑</button><button v-if="['DRAFT','RETURNED'].includes(selected.editorialState)" class="primary" :disabled="busy" @click="command('submit')">提交审核</button>
<template v-if="canPublish">
<button v-if="selected.editorialState==='SUBMITTED'" class="primary" :disabled="busy" @click="command('approve')">批准当前内容版本</button><button v-if="selected.editorialState==='SUBMITTED'" @click="openAction('return')">填写原因退回</button>
<button v-if="selected.editorialState==='APPROVED'" class="primary" @click="openAction('schedule')">选择发布时间</button><button v-if="selected.editorialState==='SCHEDULED'" :disabled="busy" @click="command('pause')">暂停这篇排期</button><button v-if="selected.editorialState==='PAUSED'" class="primary" :disabled="busy" @click="command('resume')">恢复这篇排期</button>
<button v-if="['SUBMITTED','APPROVED','SCHEDULED','PAUSED','FAILED','LEGACY','CANCELLED'].includes(selected.editorialState)&&!historical&&!['PUBLISHED','WITHDRAWN'].includes(selected.state)" :disabled="busy" @click="command('cancel')">撤回流程并返回草稿</button><button v-if="selected.state==='PUBLISHED'&&!selected.revisionId" @click="openAction('withdraw')">填写原因下架</button><button v-if="selected.state==='WITHDRAWN'" @click="openAction('restore')">核对原批准版本并恢复发布</button>
</template><button v-if="selected.state==='PUBLISHED'&&!selected.revisionId" :disabled="busy" @click="createRevision">创建私有修订稿</button><button @click="exportLedger">导出发布台账</button></div>
<p class="notice">{{ nextStep }}<span v-if="!canPublish"> 当前为编辑账号，审核批准、排期及下架由发布人员办理。</span></p>
<div class="review-layout"><section><div class="preview-heading"><h3>正文预览</h3><div role="group" aria-label="预览尺寸"><button :aria-pressed="previewMode==='desktop'" @click="previewMode='desktop'">电脑</button><button :aria-pressed="previewMode==='mobile'" @click="previewMode='mobile'">手机</button><button @click="previewRefresh++">刷新预览</button><a :href="previewUrl" target="_blank" rel="noopener noreferrer">单独查看预览 ↗</a></div></div><p class="preview-hint">{{ previewMode==='mobile' ? '按 390 像素手机宽度查看。' : '按 1280 像素电脑宽度查看。' }}预览区可横向滚动；当前显示已保存版本。</p><div class="preview-scroll"><iframe ref="previewFrame" :key="previewUrl" :src="previewUrl" :style="{width:previewMode==='mobile'?'390px':'1280px'}" title="文章排版预览" sandbox="allow-same-origin"></iframe></div></section><aside>
<section v-if="selected.images?.length"><h3>新闻封面</h3><p>从本稿已保存配图选择，调整后需要重新审核。</p><div class="cover-picker"><figure v-for="image in selected.images" :key="image.id"><img :src="image.url" :alt="image.description" loading="lazy"><figcaption>{{ image.description }}</figcaption><button :disabled="busy||!mediaEditable||image.isCover" :aria-label="image.isCover ? `当前封面：${image.description}` : `设为封面：${image.description}`" @click="setCover(image.id)">{{ image.isCover ? '当前封面' : '设为封面' }}</button></figure></div><button v-if="mediaEditable&&selected.coverId" :disabled="busy" @click="setCover(null)">不使用封面</button></section>
<section><h3>责任与使用依据</h3><dl><dt>内容来源</dt><dd>{{ sourceName(selected.sourceType) }}</dd><dt>作者／原发布方</dt><dd>{{ selected.authorName||'尚未填写' }}</dd><dt>负责编辑</dt><dd>{{ selected.editorName||'尚未填写' }}</dd><dt>使用依据</dt><dd>{{ selected.rightsBasis||'尚未填写' }}</dd><dt>使用范围</dt><dd>{{ selected.rightsScope||'尚未填写' }}</dd><dt>授权到期</dt><dd>{{ date(selected.rightsValidUntil) }}</dd></dl><details v-if="selected.rightsEvidence"><summary>授权凭证说明（仅后台可见）</summary><p class="preserve">{{ selected.rightsEvidence }}</p></details></section>
<section><h3>核验来源</h3><p v-for="(source,index) in selected.sources" :key="index"><a v-if="source.url" :href="source.url" rel="noopener noreferrer" target="_blank">{{ source.title||'未填来源名称' }} ↗</a><span v-else>来源尚未补齐</span></p><p v-if="!selected.sources?.length">尚未补充来源</p><h3>关联产品</h3><p>{{ productNames(selected.relatedProducts)||'未关联具体产品' }}</p></section>
<section v-if="selected.materials?.length"><h3>配图使用记录（仅后台可见）</h3><div v-for="(material,index) in selected.materials" :key="index"><strong>{{ material.description }}</strong><p>{{ material.basis }}</p><small>{{ material.actorName }} · {{ date(material.createdAt) }}</small></div></section><section v-if="mediaEditable" ref="mediaPanel"><h3>添加配图</h3><form @submit.prevent="uploadMedia"><label>图片说明<input v-model.trim="mediaAlt" required maxlength="240"></label><label>图片使用依据<input v-model.trim="mediaBasis" required minlength="8" maxlength="1000"></label><label>选择图片<input ref="mediaInput" type="file" accept="image/png,image/jpeg,image/webp" required></label><button :disabled="busy">上传并加入草稿</button></form><p>每张不超过 4 兆字节，上传后仍需审核。内部图片在正式发布前不会公开。</p></section>
</aside></div><section v-if="selected.history?.length"><h3>保留的公开与修订版本</h3><button v-for="item in selected.history" :key="item.id" class="history" :disabled="busy" @click="openArticle(selected.id,item.id)">第 {{ item.number }} 版 · {{ item.stateName }} · {{ date(item.appliedAt||item.updatedAt) }}</button></section>
</template>
<template v-else-if="section==='overview'&&!loading&&!error"><p :class="{error:!overview.health?.running}">{{ overview.health?.message||'发布状态尚未读取' }}</p><div class="metrics"><button v-for="item in overviewCards" :key="item.state" @click="showState(item.state)"><strong>{{ overview.counts?.[item.state]||0 }}</strong><span>{{ item.name }}</span></button></div><section><h2>从稿件到公开文章</h2><p>保存草稿并补齐资料 → 提交审核 → 核对具体版本、退回或批准 → 明确选择发布时间 → 独立任务执行 → 官网回读。</p><p>关闭浏览器不会取消已保存计划。修订在批准并发布前不改变原公开正文。</p><button class="primary" @click="switchSection('articles')">进入文章管理</button></section></template>
<template v-else-if="section==='audit'&&!loading&&!error"><div class="audit-list"><article v-for="event in events" :key="event.id"><strong>{{ event.actionName }}</strong><time>{{ date(event.createdAt) }}</time><span>{{ event.actorName||'官网工作人员' }}</span><p v-if="event.reason">{{ event.reason }}</p><button v-if="event.articleId" @click="openArticle(event.articleId)">查看对应文章</button></article><p v-if="!events.length">还没有操作记录。</p></div><div class="pagination"><button :disabled="page<=1" @click="changePage(-1)">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 条</span><button :disabled="page*30>=total" @click="changePage(1)">下一页</button></div></template>
<template v-else-if="section!=='overview'&&section!=='audit'">
<form class="filters" @submit.prevent="applyFilters"><label>标题搜索<input v-model.trim="filters.q" maxlength="80" placeholder="输入文章标题"></label><label>栏目<select v-model="filters.category"><option value="">全部栏目</option><option v-for="item in categories" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>关联产品<select v-model="filters.product"><option value="">全部产品</option><option v-for="product in products" :key="product.key" :value="product.key">{{ product.name }}</option></select></label><label>状态<select v-model="filters.state"><option value="">全部状态</option><option v-for="item in stateOptions" :key="item.state" :value="item.state">{{ item.name }}</option></select></label><label v-if="section==='plan'">发布日期（北京时间）<input v-model="filters.day" type="date"></label><button :disabled="loading">筛选</button></form>
<p v-if="section==='review'" class="notice">核对正文、来源与授权后批准当前版本；有问题请填写具体原因退回。</p><p v-if="section==='plan'" class="notice">按状态核对排期、暂停和异常。发布时间按北京时间显示。</p><p v-if="section==='materials'" class="notice">按文章核对配图、来源与依据，私有凭证只在后台展开。</p>
<div v-if="!error" class="article-list"><article v-for="item in articles" :key="item.id"><div><span class="tag">{{ item.pendingRevision?.editorialStateName||item.editorialStateName }}</span><span>{{ item.categoryName }}</span><h2><button @click="openArticle(item.id,item.pendingRevision?.revisionId)">{{ item.pendingRevision?.title||item.title }}</button></h2><p>{{ item.summary }}</p><p v-if="item.pendingRevision">有私有修订 · 原文状态：{{ item.stateName }}</p><p v-if="item.issue" class="error">{{ item.issue }}</p></div><div class="row-actions"><time>{{ date(item.pendingRevision?.scheduledAt||item.scheduledAt||item.updatedAt) }}</time><button @click="openArticle(item.id,item.pendingRevision?.revisionId)">{{ section==='materials' ? '核对素材与来源' : section==='review' ? '打开审核工作区' : '查看并办理' }}</button><a v-if="item.state==='PUBLISHED'" :href="item.url">公开文章 ↗</a></div></article><p v-if="!articles.length&&!loading&&!error">当前筛选条件下没有文章。</p></div><div class="pagination"><button :disabled="page<=1||loading" @click="changePage(-1)">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 篇</span><button :disabled="page*20>=total||loading" @click="changePage(1)">下一页</button></div>
<details v-if="section==='articles'" ref="batchPanel" :open="batchOpened" class="batch"><summary>新闻包导入与整包处理</summary><NewsBatchView v-if="batchOpened" :can-publish="canPublish" @open-article="openArticle"/><button v-else @click="batchOpened=true">打开新闻包导入工作区</button></details>
</template>
</main>
<dialog ref="actionDialog"><form @submit.prevent="submitAction"><h2>{{ actionTitle }}</h2><p>{{ selected?.title }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><label v-if="['return','withdraw','restore'].includes(dialogAction)">具体原因<textarea v-model.trim="reason" required minlength="4" maxlength="1000" rows="4"></textarea></label><template v-if="['schedule','restore'].includes(dialogAction)"><label>发布时间（北京时间）<input v-model="publishTime" @input="immediate=false" type="datetime-local" required></label><button type="button" @click="immediate=true;publishTime=localTime(new Date())">选择立即发布</button><p v-if="immediate">已选择立即交给发布任务。</p><p>任务在选定时间后执行，关闭页面仍会继续。</p></template><footer><button type="button" @click="actionDialog.close()">返回核对</button><button class="primary" :disabled="busy">{{ busy ? '正在处理…' : actionTitle }}</button></footer></form></dialog>
</div>
</template>
<script setup>
import {computed,ref,reactive,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import NewsEditor from './NewsEditor.vue'
import NewsBatchView from './NewsBatchView.vue'
import {websiteNewsApi as api} from '@/services/websiteNews.api.js'
defineProps({canPublish:Boolean})
const route=useRoute(),router=useRouter()
const tabs=[{key:'overview',name:'运营概览'},{key:'articles',name:'文章管理'},{key:'review',name:'待审核'},{key:'plan',name:'发布计划'},{key:'materials',name:'素材与来源'},{key:'audit',name:'操作记录'}]
const section=ref(tabs.some(t=>t.key===route.query.section)?route.query.section:'overview')
const stateOptions=[{state:'DRAFT',name:'草稿'},{state:'SUBMITTED',name:'待审核'},{state:'RETURNED',name:'已退回'},{state:'APPROVED',name:'已批准，待排期'},{state:'SCHEDULED',name:'待发布'},{state:'PAUSED',name:'已暂停'},{state:'FAILED',name:'发布异常'},{state:'PUBLISHED',name:'已发布'},{state:'WITHDRAWN',name:'已下架'},{state:'LEGACY',name:'原有稿件，待核对'}]
const overviewCards=stateOptions.filter(i=>['DRAFT','SUBMITTED','RETURNED','APPROVED','SCHEDULED','FAILED'].includes(i.state))
const filters=reactive({q:String(route.query.q||''),category:String(route.query.category||''),product:String(route.query.product||''),state:String(route.query.state||''),day:String(route.query.day||'')})
const page=ref(Math.max(1,Number(route.query.page)||1)),categories=ref([]),products=ref([]),articles=ref([]),events=ref([]),total=ref(0),overview=ref({}),selected=ref(null),editing=ref(null),batchOpened=ref(false)
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),actionDialog=ref(null),dialogAction=ref(''),reason=ref(''),publishTime=ref(''),mediaInput=ref(null),mediaAlt=ref(''),mediaBasis=ref(''),immediate=ref(false)
const previewMode=ref('desktop'),previewFrame=ref(null),mediaPanel=ref(null),previewRefresh=ref(0)
const batchPanel=ref(null)
async function openPackageImport(){await switchSection('articles');batchOpened.value=true;await nextTick();batchPanel.value?.scrollIntoView({block:'start'})}
let generation=0,articleGeneration=0,alive=true
const historical=computed(()=>['BASELINE','APPLIED'].includes(selected.value?.editorialState))
const editable=computed(()=>!historical.value&&['DRAFT','RETURNED','APPROVED','LEGACY'].includes(selected.value?.editorialState)&&!['SCHEDULED','PUBLISHED','WITHDRAWN'].includes(selected.value?.state))
const mediaEditable=computed(()=>editable.value&&['DRAFT','RETURNED','APPROVED'].includes(selected.value?.editorialState))
const previewUrl=computed(()=>{if(!selected.value)return '';const params=new URLSearchParams({version:String(selected.value.packageVersion),refresh:String(previewRefresh.value)});if(selected.value.revisionId)params.set('revisionId',selected.value.revisionId);return `/api/manage/news/articles/${selected.value.id}/preview?${params}`})
const nextStep=computed(()=>({DRAFT:'补齐稿件、责任与授权资料后提交审核。',RETURNED:'按退回原因修改，再次提交同一稿件。',SUBMITTED:'等待发布人员核对本次具体内容。',APPROVED:'本版本已获批准，请明确选择发布时间。',SCHEDULED:'计划已保存，由独立发布任务执行。',PAUSED:'这篇计划已暂停，恢复后才会继续。',FAILED:'撤回流程、修复发布异常后重新审核。',PUBLISHED:'更正内容时先创建私有修订稿。',WITHDRAWN:'恢复前须核对原批准版本和有效授权。'}[selected.value?.editorialState]||'核对现有资料及版本，不自动恢复旧批准。'))
const actionTitle=computed(()=>({return:'说明原因并退回',schedule:'确认发布时间',withdraw:'说明原因并下架',restore:'核对并恢复发布'}[dialogAction.value]||'确认操作'))
const date=v=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v)):'未设置'
const sourceName=v=>({original:'原创','licensed-repost':'有授权转载',unverified:'原有内容，待核对'}[v]||'待核对')
function productNames(keys){return(keys||[]).map(k=>products.value.find(p=>p.key===k)?.name).filter(Boolean).join('、')}
function localTime(v){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(v).replace(' ','T')}
function saveLocation(){router.replace({query:{section:section.value,...Object.fromEntries(Object.entries(filters).filter(([,v])=>v)),page:String(page.value)}})}
async function refresh(){const n=++generation;loading.value=true;error.value='';try{const d=section.value==='overview'?await api.overview():section.value==='audit'?await api.audits({page:page.value}):await api.articles({page:page.value,...filters,sort:section.value==='plan'?'scheduled':'updated'});if(!alive||n!==generation)return;if(section.value==='overview')overview.value=d;else{total.value=d.total;if(section.value==='audit')events.value=d.items;else articles.value=d.items}}catch(e){if(alive&&n===generation)error.value=e.message}finally{if(alive&&n===generation)loading.value=false}}
function closeArticle(){articleGeneration++;selected.value=null}
async function switchSection(key){articleGeneration++;section.value=key;selected.value=null;page.value=1;filters.day='';filters.state=key==='review'?'SUBMITTED':key==='plan'?'SCHEDULED':'';notice.value='';saveLocation();await refresh()}
async function applyFilters(){page.value=1;saveLocation();await refresh()}
async function showState(state){section.value='articles';filters.state=state;page.value=1;saveLocation();await refresh()}
async function changePage(delta){page.value+=delta;saveLocation();await refresh()}
async function openArticle(id,rid){const n=++articleGeneration;error.value='';try{const data=await api.article(id,rid);if(!alive||n!==articleGeneration)return;selected.value=data;notice.value=''}catch(e){if(alive&&n===articleGeneration)error.value=e.message}}
async function saved(d,options={}){editing.value=null;await openArticle(d.article.id,d.article.revisionId);notice.value='草稿已保存，尚未公开。';await refresh();await nextTick();if(options.action==='media')mediaPanel.value?.scrollIntoView({block:'start'});else if(options.action==='preview')previewFrame.value?.closest('section')?.scrollIntoView({block:'start'})}
async function refreshAll(){if(selected.value)await openArticle(selected.value.id,selected.value.revisionId);await refresh()}
function openAction(action){error.value='';immediate.value=false;dialogAction.value=action;reason.value='';publishTime.value=localTime(new Date(Date.now()+300000));actionDialog.value.showModal()}
async function command(action,extra={}){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{const s=selected.value,b={expectedVersion:s.packageVersion,revisionId:s.revisionId||null,reviewDigest:s.contentDigest,...extra};if(action==='withdraw')await api.withdraw(s.id,b);else if(action==='restore')await api.restore(s.id,b);else await api.action(s.id,action,b);await openArticle(s.id,s.revisionId);notice.value='操作已由官网服务保存。'+nextStep.value;await refresh();return true}catch(e){error.value=e.message;return false}finally{busy.value=false}}
async function submitAction(){const e={reason:reason.value};if(['schedule','restore'].includes(dialogAction.value))e.publishAt=immediate.value?new Date().toISOString():new Date(`${publishTime.value}:00+08:00`).toISOString();if(await command(dialogAction.value,e))actionDialog.value.close()}
async function createRevision(){busy.value=true;error.value='';try{const d=await api.revision(selected.value.id,{expectedVersion:selected.value.packageVersion});await openArticle(d.article.id,d.article.revisionId);notice.value='私有修订已建立，原公开正文保持原版本。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function uploadMedia(){const file=mediaInput.value?.files?.[0];if(!file||busy.value)return;busy.value=true;error.value='';try{const s=selected.value,params={expectedVersion:s.packageVersion,alt:mediaAlt.value,basis:mediaBasis.value};if(s.revisionId)params.revisionId=s.revisionId;await api.media(s.id,file,params);await openArticle(s.id,s.revisionId);mediaInput.value.value='';notice.value='配图已加入内部草稿，仍需审核。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function setCover(mediaId){if(!selected.value||!mediaEditable.value||busy.value)return;busy.value=true;error.value='';try{const s=selected.value;await api.cover(s.id,{expectedVersion:s.packageVersion,revisionId:s.revisionId||null,mediaId});await openArticle(s.id,s.revisionId);notice.value=mediaId?'封面已保存，请重新核对并提交审核。':'已改为不使用封面，请重新核对并提交审核。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportLedger(){try{const blob=await api.ledger(selected.value.packageId),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='新闻发布台账.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=e.message}}
onMounted(async()=>{try{const d=await Promise.all([api.categories(),api.products()]);if(!alive)return;categories.value=d[0].items;products.value=d[1].items;await refresh()}catch(e){error.value=e.message}})
onBeforeUnmount(()=>{alive=false;generation++;articleGeneration++})
</script>
